package adapter

import (
	"context"
	"os"
	"os/exec"
	"path/filepath"
	"testing"

)

// makeFixture renders a small deterministic MP4 with ffmpeg. Fixtures are
// generated by the test itself; nothing binary is committed.
func makeFixture(t *testing.T, name string, extraArgs ...string) string {
	t.Helper()
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skip("ffmpeg not available")
	}
	path := filepath.Join(t.TempDir(), name)
	args := []string{"-v", "error", "-y",
		"-f", "lavfi", "-i", "testsrc2=size=160x120:rate=25:duration=2",
		"-c:v", "libx264", "-g", "25", "-pix_fmt", "yuv420p"}
	args = append(args, extraArgs...)
	args = append(args, path)
	if out, err := exec.Command("ffmpeg", args...).CombinedOutput(); err != nil {
		t.Fatalf("fixture render: %v\n%s", err, out)
	}
	return path
}

func TestProbeHealthyMP4(t *testing.T) {
	path := makeFixture(t, "ok.mp4")
	res, err := FFprobeV1{}.Probe(context.Background(), path)
	if err != nil {
		t.Fatal(err)
	}
	if res.Format != "mp4" {
		t.Errorf("format = %q", res.Format)
	}
	if res.FPS.Num != 25 || res.FPS.Den != 1 {
		t.Errorf("fps = %+v", res.FPS)
	}
	if len(res.Samples) != 50 {
		t.Errorf("samples = %d, want 50", len(res.Samples))
	}
	kf := res.Keyframes()
	if len(kf) < 2 || kf[0].Ticks != 0 {
		t.Errorf("keyframes = %v", kf)
	}
	if res.Faults.HasUnrecoverable() || res.Truncated {
		t.Errorf("healthy file flagged: %v", res.Faults)
	}
	for _, s := range res.Samples {
		if s.Offset < 0 {
			t.Error("samples must carry source offsets")
			break
		}
	}
}

func TestProbeTruncatedKeepsPrefix(t *testing.T) {
	// MPEG-TS is streamable: a tail cut must still yield the valid prefix.
	full := makeFixture(t, "full.ts", "-f", "mpegts")
	data, err := os.ReadFile(full)
	if err != nil {
		t.Fatal(err)
	}
	trunc := filepath.Join(t.TempDir(), "trunc.ts")
	if err := os.WriteFile(trunc, data[:len(data)/2], 0o644); err != nil {
		t.Fatal(err)
	}
	res, err := FFprobeV1{}.Probe(context.Background(), trunc)
	if err != nil {
		t.Fatal(err)
	}
	if res.Format != "mpegts" {
		t.Errorf("format = %q", res.Format)
	}
	if len(res.Samples) == 0 || len(res.Samples) >= 50 {
		t.Errorf("prefix samples = %d, want 1..49", len(res.Samples))
	}
}

func TestProbeGarbageFails(t *testing.T) {
	path := filepath.Join(t.TempDir(), "junk.mp4")
	if err := os.WriteFile(path, []byte("not a media file at all"), 0o644); err != nil {
		t.Fatal(err)
	}
	a := FFprobeV1{}
	if _, err := a.Probe(context.Background(), path); err == nil {
		t.Fatal("garbage input must fail")
	}
}

func TestContainerFamilyAndTimebase(t *testing.T) {
	if got := containerFamily("mov,mp4,m4a,3gp,3g2,mj2"); got != "mp4" {
		t.Errorf("family = %q", got)
	}
	if got := containerFamily("mpegts"); got != "mpegts" {
		t.Errorf("family = %q", got)
	}
	tb := parseTimebase("1/90000")
	if tb.Num != 1 || tb.Den != 90000 {
		t.Errorf("timebase = %+v", tb)
	}
	if _, err := parseFrameRate("30000/1001"); err != nil {
		t.Errorf("NTSC rate must map: %v", err)
	}
	if _, err := parseFrameRate("24000/1001"); err == nil {
		t.Error("23.976 must be rejected (not in supported set)")
	}
}

func TestKeyframesEmpty(t *testing.T) {
	res := &ProbeResult{}
	if kf := res.Keyframes(); len(kf) != 0 {
		t.Errorf("empty result keyframes = %v", kf)
	}
	v := FFprobeV1{}.Version()
	if v != "ffprobe/"+APIVersion {
		t.Errorf("version = %q", v)
	}
}
